def handle(context):
    text = str(context.get('prompt_text') or '').strip()
    normalized = ' '.join(text.lower().split())
    if not normalized:
        return {'handled': True, 'assistant_text': 'Send a message and I will route it to the right session when needed.'}
    if normalized in {'ping', 'hello', 'hi', 'help', 'status'} or normalized.startswith('status '):
        return {'handled': True, 'assistant_text': 'Entrance is active as IO/management only. Lightweight messages can be answered here; work requests are routed by skill to delegated sessions.'}
    return {'handled': False}
